import gdb,hashlib,json,struct
from pathlib import Path
events=[];back_count=0
def mem(address,length):return bytes(gdb.selected_inferior().read_memory(address,length))
def reg(name):return int(gdb.parse_and_eval('$'+name))
def array(address,count):
 raw=mem(address,count*4)
 return {'sha256':hashlib.sha256(raw).hexdigest(),'words':[v[0] for v in struct.iter_unpack('<I',raw)]}
class EndInit(gdb.FinishBreakpoint):
 def __init__(self,ptr):
  self.ptr=ptr;super().__init__(gdb.newest_frame(),internal=True);self.silent=True
 def stop(self):
  n=struct.unpack('<i',mem(self.ptr,4))[0];ptr=struct.unpack('<Q',mem(self.ptr+8,8))[0]
  events.append({'event':'mdct_init','n':n,'trig':array(ptr,n+n//4)})
  return False
class StartInit(gdb.Breakpoint):
 def stop(self):EndInit(reg('rdi'));return False
class EndBack(gdb.FinishBreakpoint):
 def __init__(self,row,ptr):
  self.row=row;self.ptr=ptr;super().__init__(gdb.newest_frame(),internal=True);self.silent=True
 def stop(self):
  self.row['output']=array(self.ptr,self.row['n']);events.append(self.row)
  if back_count>=12:
   Path(DESTINATION).write_text(json.dumps(events))
   gdb.execute('quit')
  return False
class StartBack(gdb.Breakpoint):
 def stop(self):
  global back_count
  back_count+=1
  ptr=reg('rdi');n=struct.unpack('<i',mem(ptr,4))[0]
  row={'event':'mdct_backward','index':back_count,'n':n,'input':array(reg('rsi'),n//2)}
  EndBack(row,reg('rdx'));return False
gdb.execute('set pagination off');gdb.execute('set confirm off');gdb.execute('set breakpoint pending on')
StartInit('mdct_init',internal=True);StartBack('mdct_backward',internal=True)
gdb.execute('run')

